INSERT INTO public.places (images_id,districts_id,"name","type",postal_code,map_link,description,created_at,updated_at) VALUES
	 (201,1,'Central Park','Park','10001','https://maps.example.com/centralpark','A sprawling urban park in the heart of the city, offering lush greenery and recreational activities.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (202,2,'Golden Gate Bridge','Landmark','94129','https://maps.example.com/goldengate','An iconic suspension bridge spanning the Golden Gate strait, connecting San Francisco to Marin County.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (203,3,'Grand Canyon','Natural Landmark','86023','https://maps.example.com/grandcanyon','A breathtaking canyon carved by the Colorado River, offering stunning vistas and hiking trails.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (204,4,'Times Square','Urban Area','10036','https://maps.example.com/timessquare','A vibrant commercial and entertainment hub, known for its dazzling lights, theaters, and shopping.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (205,5,'Eiffel Tower','Landmark','75007','https://maps.example.com/eiffeltower','An iconic wrought-iron lattice tower, symbolizing Paris and offering panoramic views of the city.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (206,6,'Great Wall of China','Historical Landmark','100000','https://maps.example.com/greatwall','A series of fortifications stretching across northern China, built to protect against invasions.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (207,7,'Machu Picchu','Archaeological Site','08680','https://maps.example.com/machupicchu','An ancient Incan citadel nestled in the Andes mountains, offering stunning archaeological and scenic beauty.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (208,8,'Sydney Opera House','Performing Arts Venue','2000','https://maps.example.com/sydneyoperahouse','An architectural marvel and iconic performing arts center, showcasing a variety of cultural performances.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (209,9,'Taj Mahal','Landmark','282001','https://maps.example.com/tajmahal','A magnificent white marble mausoleum, built by Mughal Emperor Shah Jahan in memory of his wife Mumtaz Mahal.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (210,10,'The Louvre','Museum','75001','https://maps.example.com/thelouvre','One of the world''s largest and most visited art museums, housing thousands of works of art and historical artifacts.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798');
INSERT INTO public.places (images_id,districts_id,"name","type",postal_code,map_link,description,created_at,updated_at) VALUES
	 (201,11,'Niagara Falls','Natural Landmark','14303','https://maps.example.com/niagarafalls','A majestic waterfall on the border of the United States and Canada, known for its beauty and power.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (202,12,'Petra','Archaeological Site','71882','https://maps.example.com/petra','An ancient city carved into rose-colored rock cliffs, located in present-day Jordan and a UNESCO World Heritage Site.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (203,13,'The Colosseum','Historical Landmark','00184','https://maps.example.com/colosseum','An ancient amphitheater in Rome, known for its architectural grandeur and historical significance as a venue for gladiatorial contests.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (204,14,'Great Barrier Reef','Natural Landmark','4802','https://maps.example.com/greatbarrierreef','The world''s largest coral reef system, stretching over 2,300 kilometers and home to diverse marine life and ecosystems.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (205,15,'Angkor Wat','Historical Landmark','17252','https://maps.example.com/angkorwat','A UNESCO World Heritage Site and the largest religious monument in the world, located in Cambodia.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (206,16,'Statue of Liberty','Landmark','10004','https://maps.example.com/statueofliberty','A symbol of freedom and democracy, located on Liberty Island in New York Harbor.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (207,17,'Santorini','Island','84700','https://maps.example.com/santorini','A stunning Greek island in the Aegean Sea, known for its white-washed buildings, stunning sunsets, and volcanic landscapes.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (208,18,'Yellowstone National Park','National Park','82190','https://maps.example.com/yellowstone','America''s first national park, known for its geothermal features, wildlife, and scenic beauty.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (209,19,'The Vatican','Historical Landmark','00120','https://maps.example.com/vatican','An independent city-state and the spiritual center of the Roman Catholic Church, housing iconic religious and artistic treasures.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798'),
	 (200,20,'The Great Sphinx of Giza','Historical Landmark','00220','https://maps.example.com/greatsphinx','A limestone statue of a mythical creature with the body of a lion and the head of a human, located on the Giza Plateau in Egypt.','2024-02-11 19:01:03.798','2024-02-11 19:01:03.798');
